 async function uploadFile(file:File,purpose:'resource'|'recording'|'cover'){
  await run('Uploading your content',async()=>{
   const current=await saveDraft();const mime=builderUploadMime(file);
   if(file.size<1||file.size>100*1024*1024)throw new Error('Choose a file up to 100 MB. Split longer recordings into lessons.');
   const result=await new Promise<{upload:{id:string;name:string;mime:string}}>((resolve,reject)=>{
    const xhr=new XMLHttpRequest();xhrRef.current=xhr;xhr.open('POST',`/api/products/${current.product.id}/uploads?name=${encodeURIComponent(file.name)}`);xhr.setRequestHeader('Content-Type',mime);xhr.setRequestHeader('X-File-Size',String(file.size));
    xhr.upload.onprogress=event=>setUploadProgress({name:file.name,percent:event.lengthComputable?Math.round(event.loaded/event.total*100):0});
    xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300)throw new Error(data.error||'Upload failed. Select the original file and retry.');resolve(data);}catch(reason){reject(reason);}};
    xhr.onerror=()=>reject(new Error('The upload was interrupted. Your saved files are safe.'));xhr.onabort=()=>reject(new Error('Upload stopped.'));xhr.send(file);
   }).finally(()=>{xhrRef.current=null;setUploadProgress(null);});
   if(purpose==='cover')update({coverUploadId:result.upload.id});
   else if(purpose==='recording'){
    const parts=[...draftRef.current.sections],existing=parts[activeSection];if(existing)parts[activeSection]={...existing,videoId:result.upload.id};else parts.push({id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),body:'',videoId:result.upload.id});update({sections:parts});
   }else update({uploadIds:[...new Set([...draftRef.current.uploadIds,result.upload.id])]});
   const saved=await saveDraft();receive(saved);setNotice(`${result.upload.name} is validated and saved privately.`);
  });
 }
